description:
Build the pool allocator from lesson 6.03, keeping the free list **inside the free blocks**:

```cpp
class Pool
{
public:
    Pool(std::size_t blockSize, std::size_t blockCount);
    void* allocate();
    void release(void* block);
    std::size_t freeCount() const;
    std::size_t blockSize() const;
    bool owns(const void* p) const;
};
```

- All blocks come from one region. The block size is rounded up to a multiple of 16 (and is at least 16), so every block is 16-aligned.
- At the start, blocks are handed out in address order: the first `allocate` returns the first block, the next the second, and so on.
- **release** puts a block back; the most recently released block is the next one `allocate` returns.
- **allocate** returns `nullptr` when every block is in use.
- **freeCount** counts free blocks (keep a counter; do not walk the list). **owns** says whether a pointer is the start of one of this pool's blocks.
- Store each free block's `next` pointer in the block's own first bytes, with `std::memcpy`.

starter.solution.cpp:
#include <cstddef>

class Pool
{
public:
    Pool(std::size_t blockSize, std::size_t blockCount) {}
    void* allocate() { return nullptr; }
    void release(void* block) {}
    std::size_t freeCount() const { return 0; }
    std::size_t blockSize() const { return 0; }
    bool owns(const void* p) const { return false; }
};

solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <new>

class Pool
{
public:
    Pool(std::size_t blockSize, std::size_t blockCount)
        : size{ blockSize < 16 ? 16 : (blockSize + 15) / 16 * 16 }, count{ blockCount },
          memory{ static_cast<std::byte*>(::operator new(size * blockCount, std::align_val_t{ 16 })) }
    {
        for (std::size_t i{ count }; i-- > 0;) push(memory + i * size);
    }
    ~Pool() { ::operator delete(memory, std::align_val_t{ 16 }); }
    Pool(const Pool&) = delete;
    Pool& operator=(const Pool&) = delete;

    void* allocate()
    {
        if (!head) return nullptr;
        std::byte* block{ head };
        std::memcpy(&head, block, sizeof(head));
        --available;
        return block;
    }

    void release(void* block) { if (block) push(static_cast<std::byte*>(block)); }

    std::size_t freeCount() const { return available; }
    std::size_t blockSize() const { return size; }

    bool owns(const void* p) const
    {
        const auto at{ reinterpret_cast<std::uintptr_t>(p) }, start{ reinterpret_cast<std::uintptr_t>(memory) };
        return at >= start && at < start + size * count && (at - start) % size == 0;
    }

private:
    void push(std::byte* block)
    {
        std::memcpy(block, &head, sizeof(head));
        head = block;
        ++available;
    }

    std::size_t size, count;
    std::byte* memory;
    std::byte* head{ nullptr };
    std::size_t available{ 0 };
};

unitTests:
#include <cstdint>
#include <vector>
static std::uintptr_t addr(const void* p) { return reinterpret_cast<std::uintptr_t>(p); }

TEST("blocks in address order at first") {
    Pool pool{ 24, 4 };
    CHECK_EQ(pool.blockSize(), 32u);
    CHECK_EQ(pool.freeCount(), 4u);
    void* a{ pool.allocate() }; void* b{ pool.allocate() }; void* c{ pool.allocate() };
    CHECK_EQ(addr(b) - addr(a), 32u);
    CHECK_EQ(addr(c) - addr(b), 32u);
    CHECK_EQ(addr(a) % 16, 0u);
    CHECK_EQ(pool.freeCount(), 1u);
}
TEST("exhausted pools return nullptr") {
    Pool pool{ 8, 2 };
    CHECK_EQ(pool.blockSize(), 16u);
    CHECK(pool.allocate() != nullptr);
    CHECK(pool.allocate() != nullptr);
    CHECK(pool.allocate() == nullptr);
    CHECK_EQ(pool.freeCount(), 0u);
}
TEST("last released, first reused") {
    Pool pool{ 64, 8 };
    void* a{ pool.allocate() }; void* b{ pool.allocate() }; void* c{ pool.allocate() };
    pool.release(a);
    pool.release(c);
    CHECK(pool.allocate() == c);
    CHECK(pool.allocate() == a);
    CHECK_EQ(addr(pool.allocate()) - addr(b), 128u);
}
TEST("blocks are usable memory") {
    Pool pool{ sizeof(double) * 4, 16 };
    std::vector<double*> blocks;
    for (int i{ 0 }; i < 16; ++i) { auto* d{ static_cast<double*>(pool.allocate()) }; for (int k{ 0 }; k < 4; ++k) d[k] = i + k * 0.5; blocks.push_back(d); }
    for (int i{ 0 }; i < 16; ++i) CHECK_EQ(blocks[i][3], i + 1.5);
    for (double* d : blocks) pool.release(d);
    CHECK_EQ(pool.freeCount(), 16u);
}
TEST("owns") {
    Pool pool{ 32, 4 };
    void* a{ pool.allocate() };
    CHECK(pool.owns(a));
    CHECK(!pool.owns(static_cast<char*>(a) + 8));
    int local{ 0 };
    CHECK(!pool.owns(&local));
    CHECK(pool.owns(static_cast<char*>(a) + 96));
    CHECK(!pool.owns(static_cast<char*>(a) + 128));
}

